 '[{"name":"番茄","amount":"2个","iconName":"tomato"},{"name":"鸡蛋","amount":"3个","iconName":"egg"},{"name":"葱","amount":"适量","iconName":"leaf"},{"name":"盐","amount":"适量","iconName":"flask"},{"name":"糖","amount":"少许","iconName":"flask"}]',
 '[{"stepNumber":1,"title":"备料打蛋","description":"番茄去蒂切滚刀块；鸡蛋 3 个打散，加 2 勺清水和少许盐搅匀至起小泡。","heat":"无需火候","durationSeconds":240,"tip":"蛋液加清水炒出来更蓬松嫩滑；想更香可滴几滴料酒去腥。","ingredients":["番茄","鸡蛋"]},{"stepNumber":2,"title":"滑炒鸡蛋","description":"热锅倒油，油温六成热倒入蛋液，待边缘凝固后从外向内推炒成大块，八成熟盛出。","heat":"中火","durationSeconds":120,"tip":"油要够热蛋才蓬松；八成熟就出锅，回锅还要再炒一次。","ingredients":["鸡蛋"]},{"stepNumber":3,"title":"炒出番茄汁","description":"锅中留底油，下番茄块中火翻炒 2 分钟，炒到番茄软塌出汁，加半勺糖和少许盐。","heat":"中火","durationSeconds":150,"tip":"加一点糖能中和番茄的酸，味道更柔和；出汁后再回蛋，汤汁才挂得住。","ingredients":["番茄"]},{"stepNumber":4,"title":"合炒出锅","description":"倒回鸡蛋块，大火快速翻炒 30 秒让蛋吸饱番茄汁，撒葱花出锅。","heat":"大火","durationSeconds":90,"tip":"合炒时间要短，翻两下就出锅，鸡蛋才嫩。","ingredients":["鸡蛋","葱"]}]',
