 '[{"name":"西兰花","amount":"300g","iconName":"leaf"},{"name":"大蒜","amount":"4瓣","iconName":"garlic"},{"name":"胡萝卜","amount":"半根","iconName":"leaf"},{"name":"蚝油","amount":"1勺","iconName":"flask"},{"name":"盐","amount":"适量","iconName":"flask"}]',
 '[{"stepNumber":1,"title":"浸泡焯水","description":"西兰花切小朵，用淡盐水浸泡 5 分钟后冲洗干净；锅中水烧开加少许盐和油，下西兰花焯 60 秒捞出过凉水。","heat":"大火","durationSeconds":360,"tip":"焯水加盐和油能保持翠绿；过凉水锁色，口感更脆。","ingredients":["西兰花"]},{"stepNumber":2,"title":"切配备料","description":"大蒜切末，胡萝卜削皮切成薄片。","heat":"无需火候","durationSeconds":180,"tip":"蒜末分两次下锅，一半爆香、一半出锅前撒，蒜香更足。","ingredients":["大蒜","胡萝卜"]},{"stepNumber":3,"title":"爆香蒜末","description":"热锅倒油，下蒜末小火煸至微黄出香。","heat":"小火","durationSeconds":60,"tip":"蒜末小火慢煸才香，大火容易焦苦。","ingredients":["大蒜"]},{"stepNumber":4,"title":"大火快炒","description":"转大火下胡萝卜片炒 30 秒，倒入西兰花，加盐和 1 勺蚝油快速翻炒均匀出锅。","heat":"大火","durationSeconds":120,"tip":"焯过的西兰花已经半熟，回锅只需炒匀调味，久炒会变软发黄。","ingredients":["西兰花","胡萝卜","盐"]}]',
 0),
(6, '红烧排骨', '酱香浓郁，骨肉分离', '/images/6.jpg',
