 '[{"stepNumber":1,"title":"排骨焯水","description":"猪肋排剁成 5cm 段，冷水下锅，加姜片和料酒，大火煮沸撇沫，煮 3 分钟后捞出用温水冲净。","heat":"大火","durationSeconds":360,"tip":"冷水下锅才能把血水逼出来；温水冲洗避免排骨遇冷收缩。","ingredients":["猪肋排","姜片"]},{"stepNumber":2,"title":"炒糖色","description":"锅中放少量油，下冰糖小火慢炒至融化变枣红色冒小泡，立刻倒入排骨翻炒裹匀。","heat":"小火","durationSeconds":240,"tip":"糖色炒到枣红就要立刻下排骨，再炒几秒就会发苦。","ingredients":["冰糖","猪肋排"]},{"stepNumber":3,"title":"加料炖煮","description":"加八角、桂皮、姜片炒香，烹入生抽和老抽，冲入没过排骨的开水，大火烧开转小火加盖炖 40 分钟。","heat":"大火转小火","durationSeconds":2400,"tip":"一定加开水，冷水会让肉变硬；水一次加够，中途别添水。","ingredients":["八角","桂皮"]},{"stepNumber":4,"title":"大火收汁","description":"开盖转大火收汁 5 分钟，汤汁浓稠裹住排骨即可关火装盘。","heat":"大火","durationSeconds":300,"tip":"收汁时勤翻动防止糊底；汤汁挂勺就关火，收过头会发苦发咸。","ingredients":["猪肋排"]}]',
