 '[{"stepNumber":1,"title":"牛肉切片上浆","description":"牛里脊逆纹切成 2mm 薄片，加 1 勺料酒、1 个蛋清、2 勺淀粉和少许盐抓打至发黏，封 1 勺油腌 15 分钟。","heat":"无需明火","durationSeconds":900,"tip":"逆纹切断纤维才嫩；最后封油锁水，下锅才不脱浆。","ingredients":["牛里脊","淀粉"]},{"stepNumber":2,"title":"豆芽焯水垫底","description":"黄豆芽掐根洗净，沸水中加少许盐焯 1 分钟捞出，沥干铺在大碗底部。","heat":"大火","durationSeconds":90,"tip":"豆芽垫底既吸汁又解腻，焯水可去豆腥。","ingredients":["豆芽"]},{"stepNumber":3,"title":"炒制红汤","description":"锅中放 2 勺油，中火下郫县豆瓣酱炒至出红油翻沙，加蒜末和一半干辣椒段炒香，冲入 500ml 高汤烧开。","heat":"中火","durationSeconds":300,"tip":"豆瓣酱务必炒到「红油翻沙」再加水，汤色才红亮不发浑。","ingredients":["豆瓣酱","蒜末","干辣椒"]},{"stepNumber":4,"title":"汆烫牛肉","description":"转中小火，把牛肉片抖散逐片下锅，静置 10 秒再轻推，煮至肉片全部变白约 40 秒立即关火。","heat":"中小火","durationSeconds":60,"tip":"下锅别马上搅动，否则脱浆；变色即熟，久煮必老。","ingredients":["牛里脊"]},{"stepNumber":5,"title":"泼油激香","description":"肉片连汤倒入碗中，表面撒剩余干辣椒段与花椒，另起锅烧 3 勺油至冒青烟，一次泼在辣椒上。","heat":"大火","durationSeconds":60,"tip":"油温须达约 220℃ 才能激出麻辣香，温油只剩生辣味。","ingredients":["干辣椒","花椒"]},{"stepNumber":6,"title":"点缀上桌","description":"撒蒜末与小葱花，趁热食用。","heat":"无需明火","durationSeconds":30,"tip":"现泼现吃，麻香最足。","ingredients":["蒜末"]}]',
 1),
