 '[{"name":"猪里脊","amount":"250g","iconName":"beef"},{"name":"木耳","amount":"50g","iconName":"leaf"},{"name":"胡萝卜","amount":"半根","iconName":"leaf"},{"name":"泡椒","amount":"3个","iconName":"flask"},{"name":"蒜末","amount":"3瓣","iconName":"garlic"}]',
 '[{"stepNumber":1,"title":"里脊切丝腌制","description":"猪里脊顺纹片薄再逆纹切 3mm 粗丝，加 1 勺生抽、1 勺料酒、1 勺淀粉抓匀，封油腌 10 分钟；木耳泡发切丝，胡萝卜切丝。","heat":"无需明火","durationSeconds":600,"tip":"切丝要粗细均匀才同步成熟；封油防粘连。","ingredients":["猪里脊","生抽","淀粉","木耳","胡萝卜"]},{"stepNumber":2,"title":"调鱼香汁","description":"碗中放香醋 2 勺、白糖 2 勺、生抽 1 勺、淀粉 半勺、清水 3 勺调匀成鱼香汁。","heat":"无需明火","durationSeconds":90,"tip":"先把汁调好再开火，川菜讲究「一锅成菜」，中途来不及配料。","ingredients":["香醋","白糖","生抽","淀粉"]},{"stepNumber":3,"title":"滑炒肉丝","description":"热锅冷油烧至四成热（约 120℃），下肉丝快速滑散，一变色立刻盛出。","heat":"中火","durationSeconds":45,"tip":"温油滑炒肉才嫩；油温过高会结团发柴。","ingredients":["猪里脊"]},{"stepNumber":4,"title":"爆香下配菜","description":"锅内留底油，下泡椒末、蒜末、姜末炒出红油，倒入木耳丝、胡萝卜丝大火翻炒 1 分钟。","heat":"中火","durationSeconds":90,"tip":"泡椒是鱼香味灵魂，要炒出乳酸香。","ingredients":["泡椒","蒜末","木耳","胡萝卜"]},{"stepNumber":5,"title":"合炒收汁","description":"倒回肉丝，沿锅边淋入鱼香汁，大火颠翻至芡汁亮油裹匀，撒葱花出锅。","heat":"大火","durationSeconds":40,"tip":"汁入锅后要大火快炒，芡一浓即可，久炒发酸。","ingredients":["猪里脊"]}]',
 0),
