 '[{"name":"五花肉","amount":"400g","iconName":"beef"},{"name":"蒜苗","amount":"3根","iconName":"leaf"},{"name":"青椒","amount":"2个","iconName":"leaf"},{"name":"豆瓣酱","amount":"2勺","iconName":"flask"},{"name":"甜面酱","amount":"1勺","iconName":"flask"}]',
 '[{"stepNumber":1,"title":"煮肉断生","description":"五花肉整块冷水下锅，加姜片、葱段、1 勺料酒，中火煮 15 分钟至筷子能扎透，捞出晾凉。","heat":"中火","durationSeconds":900,"tip":"煮到七成熟即可，中心微粉最好，太熟炒时易碎。","ingredients":["五花肉","姜片"]},{"stepNumber":2,"title":"切灯盏片","description":"晾凉的肉切成 2mm 薄片，蒜苗斜切段，青椒切菱形块。","heat":"无需明火","durationSeconds":240,"tip":"肉晾凉再切才成薄片；热切会散。","ingredients":["五花肉","蒜苗","青椒"]},{"stepNumber":3,"title":"煸肉出油","description":"热锅少油，下肉片中火慢煸至肉片卷曲呈「灯盏窝」状、边缘微焦出油。","heat":"中火","durationSeconds":180,"tip":"煸出多余油脂才肥而不腻，卷曲是到位标志。","ingredients":["五花肉"]},{"stepNumber":4,"title":"炒香酱料","description":"滗出多余油，下郫县豆瓣酱、甜面酱炒出红油，加少许白糖提鲜。","heat":"中火","durationSeconds":90,"tip":"豆瓣酱炒香再下其他料，蒜苗要在最后放。","ingredients":["豆瓣酱","甜面酱","白糖"]},{"stepNumber":5,"title":"下蒜苗出锅","description":"转大火下蒜苗段、青椒块，翻炒 30 秒断生即出锅。","heat":"大火","durationSeconds":45,"tip":"蒜苗保持翠绿脆嫩，炒久会发黄出水。","ingredients":["蒜苗","青椒"]}]',
 0),
