 '[{"name":"黑鱼片","amount":"400g","iconName":"fish"},{"name":"酸菜","amount":"200g","iconName":"leaf"},{"name":"泡椒","amount":"5个","iconName":"flask"},{"name":"姜蒜","amount":"适量","iconName":"garlic"},{"name":"蛋清","amount":"1个","iconName":"egg"}]',
 '[{"stepNumber":1,"title":"鱼片码味上浆","description":"黑鱼片用少许盐、白胡椒粉、1 个蛋清、2 勺淀粉抓至发黏，腌 15 分钟；鱼骨剁块备用。","heat":"无需明火","durationSeconds":900,"tip":"鱼片用力抓才有黏性，这叫「上劲」，煮时不易散。","ingredients":["黑鱼片","蛋清","淀粉"]},{"stepNumber":2,"title":"炒酸菜","description":"锅中放油，中火下姜蒜末、泡椒炒香，加入酸菜段翻炒 3 分钟炒干水汽。","heat":"中火","durationSeconds":180,"tip":"酸菜一定要炒透去生酸，汤才醇厚不齁。","ingredients":["酸菜","泡椒","姜蒜"]},{"stepNumber":3,"title":"熬鱼汤","description":"加 800ml 热水烧开，下鱼骨中火煮 8 分钟熬出奶白汤底，捞出鱼骨垫碗底。","heat":"中火","durationSeconds":480,"tip":"加热水煮才白；鱼骨先煮出味，鱼片后下才嫩。","ingredients":["黑鱼片"]},{"stepNumber":4,"title":"汆鱼片","description":"转小火保持微沸，鱼片逐片下锅，煮 40 秒至变白立刻关火。","heat":"小火","durationSeconds":45,"tip":"汤不能大滚，否则鱼片散架。","ingredients":["黑鱼片"]},{"stepNumber":5,"title":"激香装碗","description":"鱼片连汤倒入碗中，撒干辣椒段、花椒、蒜末，泼一勺热油激香，撒葱花。","heat":"大火","durationSeconds":45,"tip":"热油泼在干料上，麻香才能瞬间释放。","ingredients":["泡椒","姜蒜"]}]',
 1),
