 '[{"stepNumber":1,"title":"切条腌味","description":"猪里脊切 1cm 见方、6cm 长条，加少许盐、白胡椒粉、1 个蛋液抓匀腌 10 分钟。","heat":"无需明火","durationSeconds":600,"tip":"先给底味再挂糊，炸后才有味。","ingredients":["猪里脊","鸡蛋"]},{"stepNumber":2,"title":"裹糊","description":"加 3 勺淀粉和 1 勺面粉拌匀，再补少许水调成能挂住筷子、缓慢滴落的糊。","heat":"无需明火","durationSeconds":120,"tip":"加一点面粉更酥；糊太稀挂不住，太稠外壳厚。","ingredients":["猪里脊","鸡蛋"]},{"stepNumber":3,"title":"初炸定型","description":"油烧至六成热（约 180℃），逐条下锅炸 90 秒至微黄捞出。","heat":"中火","durationSeconds":90,"tip":"六成热定型不吸油；下锅后先别翻动。","ingredients":["猪里脊"]},{"stepNumber":4,"title":"复炸酥脆","description":"油温升至八成热（约 200℃），回锅复炸 30 秒至金黄捞出沥油。","heat":"大火","durationSeconds":30,"tip":"复炸逼出油脂才外酥里嫩，这一步不能省。","ingredients":["猪里脊"]},{"stepNumber":5,"title":"熬糖醋汁","description":"锅中加番茄酱 3 勺、白糖 2 勺、白醋 2 勺、清水 3 勺，中火熬至冒大泡略稠。","heat":"中火","durationSeconds":120,"tip":"糖醋比约 1:1，熬到能挂勺再下肉。","ingredients":["番茄酱","白糖","白醋"]},{"stepNumber":6,"title":"翻裹装盘","description":"倒入炸好的里脊，快速颠翻 15 秒使每根裹匀亮汁，出锅。","heat":"大火","durationSeconds":20,"tip":"动作要快，久翻外壳会回软。","ingredients":["猪里脊"]}]',
