 '[{"name":"排骨","amount":"400g","iconName":"beef"},{"name":"冬瓜","amount":"400g","iconName":"leaf"},{"name":"姜片","amount":"3片","iconName":"leaf"},{"name":"枸杞","amount":"10g","iconName":"leaf"},{"name":"盐","amount":"适量","iconName":"flask"}]',
 '[{"stepNumber":1,"title":"排骨焯水","description":"排骨冷水下锅，加姜片和 1 勺料酒，大火煮沸撇净浮沫后煮 2 分钟，温水冲净。","heat":"大火","durationSeconds":300,"tip":"冷水下锅血沫才出得净，汤才清不腥。","ingredients":["排骨","姜片"]},{"stepNumber":2,"title":"first 炖骨","description":"砂锅加足量清水放排骨与姜片，大火烧开转小火加盖炖 40 分钟。","heat":"大火转小火","durationSeconds":2400,"tip":"一次加足水，中途加水会冲淡汤味。","ingredients":["排骨","姜片"]},{"stepNumber":3,"title":"下冬瓜","description":"冬瓜去皮去瓤切 2cm 厚块，下锅继续小火炖 15 分钟至半透明。","heat":"小火","durationSeconds":900,"tip":"冬瓜后放，久煮会化汤。","ingredients":["冬瓜"]},{"stepNumber":4,"title":"调味","description":"加盐调味，撒枸杞再煮 2 分钟关火。","heat":"小火","durationSeconds":120,"tip":"盐最后放，早放排骨不易酥烂。","ingredients":["盐","枸杞"]}]',
 0),
(26, '玉米排骨汤', '清甜浓郁，营养滋补', '/images/26.jpg',
