 '[{"name":"排骨","amount":"400g","iconName":"beef"},{"name":"玉米","amount":"2根","iconName":"leaf"},{"name":"胡萝卜","amount":"1根","iconName":"leaf"},{"name":"姜片","amount":"3片","iconName":"leaf"},{"name":"盐","amount":"适量","iconName":"flask"}]',
 '[{"stepNumber":1,"title":"排骨焯水","description":"排骨冷水下锅，加姜片、料酒，大火煮沸撇沫煮 2 分钟后温水冲净。","heat":"大火","durationSeconds":300,"tip":"去净血沫汤才清甜不腥。","ingredients":["排骨","姜片"]},{"stepNumber":2,"title":"备料","description":"玉米切段，胡萝卜滚刀切块。","heat":"无需明火","durationSeconds":180,"tip":"玉米留一两层嫩衣煮更甜（可选）。","ingredients":["玉米","胡萝卜"]},{"stepNumber":3,"title":"同炖","description":"所有食材入砂锅加足量水，大火烧开转小火加盖炖 50 分钟。","heat":"大火转小火","durationSeconds":3000,"tip":"全程小火微沸，汤清味浓。","ingredients":["排骨","玉米","胡萝卜","姜片"]},{"stepNumber":4,"title":"调味","description":"出锅前加盐调味即可，撒少许葱花。","heat":"小火","durationSeconds":60,"tip":"盐最后放，保持肉质酥嫩。","ingredients":["盐"]}]',
