 '[{"stepNumber":1,"title":"泡发","description":"银耳冷水泡发 2 小时至完全舒展，剪去黄色硬蒂撕成小朵；莲子温水泡 1 小时去芯。","heat":"无需明火","durationSeconds":300,"tip":"银耳必须冷水泡透才易出胶；黄蒂不剪会带苦味。","ingredients":["银耳","莲子"]},{"stepNumber":2,"title":"煮出胶","description":"银耳莲子入锅加 1200ml 水，大火烧开转小火炖 40 分钟至汤汁黏稠出胶。","heat":"大火转小火","durationSeconds":2400,"tip":"水一次加足；小火慢炖银耳才拉丝。","ingredients":["银耳","莲子"]},{"stepNumber":3,"title":"加红枣冰糖","description":"加红枣和冰糖继续炖 15 分钟。","heat":"小火","durationSeconds":900,"tip":"红枣后放不易烂；冰糖比白糖更清亮。","ingredients":["红枣","冰糖"]},{"stepNumber":4,"title":"撒枸杞出锅","description":"关火前 3 分钟撒枸杞，焖 5 分钟即可。","heat":"小火","durationSeconds":180,"tip":"枸杞久煮会发酸，最后放。","ingredients":["枸杞"]}]',
 0),
