 '[{"stepNumber":1,"title":"牛腩焯水","description":"牛腩切 3cm 块冷水下锅，加姜片料酒煮沸撇沫煮 3 分钟，温水冲净。","heat":"大火","durationSeconds":300,"tip":"冷水下锅血沫出得净，汤更清。","ingredients":["牛腩","姜片"]},{"stepNumber":2,"title":"炒番茄底","description":"番茄去皮切块，洋葱切丁；热油炒香洋葱，下番茄中火炒 5 分钟至出沙。","heat":"中火","durationSeconds":300,"tip":"番茄炒出沙是汤底红亮的关键。","ingredients":["番茄","洋葱"]},{"stepNumber":3,"title":"炖牛腩","description":"下牛腩翻炒上色，加足量热水，大火烧开转小火炖 40 分钟至软烂。","heat":"大火转小火","durationSeconds":2400,"tip":"加热水炖肉不柴，小火慢炖出胶质。","ingredients":["牛腩"]},{"stepNumber":4,"title":"调味","description":"加盐、少许糖调味，保持汤底微浓。","heat":"小火","durationSeconds":60,"tip":"糖只提鲜不显甜。","ingredients":["盐"]},{"stepNumber":5,"title":"煮面装碗","description":"面条按包装煮至弹牙，捞入碗中浇上牛腩汤与肉块，撒葱花。","heat":"大火","durationSeconds":300,"tip":"面条略硬一分捞出（al dente），泡汤不糊。","ingredients":["面条"]}]',
