 '[{"name":"细面条","amount":"150g","iconName":"leaf"},{"name":"小葱","amount":"3根","iconName":"leaf"},{"name":"猪油","amount":"1勺","iconName":"flask"},{"name":"生抽","amount":"2勺","iconName":"flask"},{"name":"高汤","amount":"适量","iconName":"flask"}]',
 '[{"stepNumber":1,"title":"熬葱油","description":"小葱切段，冷油下葱段小火慢炸 8 分钟至葱段焦黄捞出，得葱油。","heat":"小火","durationSeconds":480,"tip":"冷油下葱、小火慢炸，葱香才不回苦。","ingredients":["小葱","猪油"]},{"stepNumber":2,"title":"调碗底","description":"碗中放生抽 2 勺、猪油 1 勺、葱油 1 勺、少许盐和白糖。","heat":"无需明火","durationSeconds":60,"tip":"猪油是阳春面的灵魂，缺它不香。","ingredients":["生抽","猪油"]},{"stepNumber":3,"title":"煮面","description":"宽水烧开下面条，煮 2 分钟至刚断生。","heat":"大火","durationSeconds":120,"tip":"水要宽、火要旺，面才爽滑不粘。","ingredients":["细面条"]},{"stepNumber":4,"title":"冲汤","description":"碗底冲入 200ml 滚烫高汤，搅匀化开猪油。","heat":"大火","durationSeconds":30,"tip":"必须先冲汤再放面，汤才清亮。","ingredients":["高汤"]},{"stepNumber":5,"title":"捞面撒葱","description":"捞入面条，撒葱花和几根炸葱段即成。","heat":"无需明火","durationSeconds":30,"tip":"趁热吃，面泡久会涨。","ingredients":["小葱"]}]',
