 '[{"stepNumber":1,"title":"打馅上劲","description":"猪肉末加姜末、1 勺生抽、少许盐和 3 勺花椒水，顺一个方向搅打至黏稠起胶。","heat":"无需明火","durationSeconds":300,"tip":"分次打水、同向搅打，馅才多汁抱团。","ingredients":["猪肉末","姜末"]},{"stepNumber":2,"title":"拌三鲜馅","description":"虾仁切丁、韭菜切末，加香油拌入肉馅，冷藏 20 分钟。","heat":"无需明火","durationSeconds":1200,"tip":"韭菜先用油封住切口不出水；冷藏后更好包。","ingredients":["虾仁","韭菜"]},{"stepNumber":3,"title":"包饺子","description":"取饺子皮放馅，对折捏紧收口，摆盘撒粉防粘。","heat":"无需明火","durationSeconds":900,"tip":"边缘捏严不留缝，煮时才不破。","ingredients":["饺子皮"]},{"stepNumber":4,"title":"煮饺子","description":"宽水沸后下饺子，轻推防粘，水再沸点 1 次凉水，共点 3 次。","heat":"大火","durationSeconds":300,"tip":"点凉水让皮馅同步熟，饺子鼓肚浮起即熟。","ingredients":["饺子皮"]},{"stepNumber":5,"title":"配碟上桌","description":"捞出沥水，配醋、蒜泥、辣油碟食用。","heat":"无需明火","durationSeconds":60,"tip":"现煮现吃最鲜。","ingredients":["饺子皮"]}]',
