 '[{"stepNumber":1,"title":"和面醒面","description":"面粉 300g 加约 180ml 温水（约 60℃）揉成软面团，盖布醒 20 分钟。","heat":"无需明火","durationSeconds":1200,"tip":"半烫面既软又有筋，烙后不硬。","ingredients":["面粉"]},{"stepNumber":2,"title":"炒蛋拌馅","description":"鸡蛋炒碎放凉，韭菜切细末，加虾皮、香油、少许盐拌匀。","heat":"中火","durationSeconds":180,"tip":"韭菜先拌油再放盐，锁水不出汤。","ingredients":["鸡蛋","韭菜","虾皮","香油"]},{"stepNumber":3,"title":"擀皮包制","description":"面团分剂擀成圆皮，放馅对折成半月，捏紧边缘压出花边。","heat":"无需明火","durationSeconds":600,"tip":"边缘捏紧防漏；花边既好看又封口。","ingredients":["面粉"]},{"stepNumber":4,"title":"烙制","description":"平底锅少油中火，放入盒子烙 3 分钟至底面金黄，翻面再烙 2 分钟。","heat":"中火","durationSeconds":300,"tip":"中小火慢烙，皮熟馅香不夹生。","ingredients":["面粉"]},{"stepNumber":5,"title":"切块食用","description":"出锅稍晾切两半，配醋食用。","heat":"无需明火","durationSeconds":60,"tip":"稍晾再切，韭菜馅不烫口。","ingredients":["韭菜"]}]',
