 '[{"stepNumber":1,"title":"泡米煮粥底","description":"大米洗净加 1 勺油拌匀泡 30 分钟，加水大火烧开转小火熬 30 分钟成绵稠粥底。","heat":"大火转小火","durationSeconds":1800,"tip":"米里拌油粥更绵滑不糊底。","ingredients":["大米"]},{"stepNumber":2,"title":"腌瘦肉","description":"猪瘦肉切细丝，加少许盐、生抽、淀粉抓匀腌 10 分钟。","heat":"无需明火","durationSeconds":600,"tip":"上浆的肉丝入粥才滑嫩。","ingredients":["猪瘦肉"]},{"stepNumber":3,"title":"切皮蛋","description":"皮蛋去壳切小丁，一半入粥煮化增香，一半留作点缀。","heat":"无需明火","durationSeconds":120,"tip":"皮蛋分两次放，一半融进粥里更香。","ingredients":["皮蛋"]},{"stepNumber":4,"title":"下料","description":"粥底浓稠后下肉丝和皮蛋丁，小火搅煮 5 分钟。","heat":"小火","durationSeconds":300,"tip":"边煮边搅防糊底，肉丝变白即熟。","ingredients":["猪瘦肉","皮蛋"]},{"stepNumber":5,"title":"调味","description":"加盐、白胡椒粉调味，撒姜丝和葱花出锅。","heat":"小火","durationSeconds":60,"tip":"白胡椒提香去腥，姜丝解腻。","ingredients":["姜丝","葱花"]}]',
