 '[{"stepNumber":1,"title":"处理大虾","description":"大虾剪去虾枪虾须，从背部开刀挑出虾线，沥干水分。","heat":"无需明火","durationSeconds":300,"tip":"开背更入味也好剥；虾线务必去净。","ingredients":["大虾"]},{"stepNumber":2,"title":"煎虾出油","description":"热锅放 2 勺油，中大火下虾煎 1 分钟至两面变红、虾头发红出虾油。","heat":"中大火","durationSeconds":120,"tip":"压一压虾头逼出虾油，这是香味来源。","ingredients":["大虾"]},{"stepNumber":3,"title":"下姜蒜炒香","description":"下姜末蒜末炒香 30 秒。","heat":"中火","durationSeconds":30,"tip":"姜蒜去腥提香，别炒糊。","ingredients":["姜蒜"]},{"stepNumber":4,"title":"调汁焖制","description":"加番茄酱 2 勺、白糖 1 勺、料酒 1 勺和 3 勺清水，加盖中火焖 5 分钟。","heat":"中火","durationSeconds":300,"tip":"焖让虾肉吸入酱汁，虾身弯曲即熟。","ingredients":["番茄酱","白糖","料酒"]},{"stepNumber":5,"title":"收汁亮芡","description":"开盖大火收汁至酱汁浓稠亮红、均匀裹在虾身，撒葱花出锅。","heat":"大火","durationSeconds":60,"tip":"收汁到「亮油挂汁」最诱人，久收会咸。","ingredients":["大虾"]}]',
