 '[{"stepNumber":1,"title":"切条腌制","description":"梅花肉切 4cm 宽长条，加叉烧酱 3 勺、生抽 1 勺、蒜末、少许糖抓匀，冷藏腌 4 小时以上（过夜更佳）。","heat":"无需明火","durationSeconds":14400,"tip":"梅花肉肥瘦相间最适合叉烧；腌足时间才入味。","ingredients":["梅花肉","叉烧酱","生抽","蒜末"]},{"stepNumber":2,"title":"回温晾干","description":"取出肉条回温 30 分钟，擦去表面多余酱汁。","heat":"无需明火","durationSeconds":1800,"tip":"表面酱汁过多易焦黑，擦掉更易上色。","ingredients":["梅花肉"]},{"stepNumber":3,"title":"烤制第一遍","description":"烤箱 200℃ 预热，肉条架在烤网上，下层垫锡纸接油，烤 20 分钟。","heat":"无需明火","durationSeconds":1200,"tip":"架烤让热风环绕，四面均匀受热。","ingredients":["梅花肉"]},{"stepNumber":4,"title":"刷蜜翻面","description":"取出翻面，刷一层蜂蜜，再烤 15 分钟。","heat":"无需明火","durationSeconds":900,"tip":"蜂蜜最后刷，早刷会焦；翻面使两面焦香。","ingredients":["蜂蜜"]},{"stepNumber":5,"title":"上色收尾","description":"再刷一次蜂蜜，转 220℃ 烤 5 分钟至表面红亮微焦。","heat":"无需明火","durationSeconds":300,"tip":"高温短烤形成焦糖外壳，即「蜜汁」。","ingredients":["蜂蜜"]},{"stepNumber":6,"title":"静置切片","description":"取出静置 10 分钟后逆纹切片。","heat":"无需明火","durationSeconds":600,"tip":"静置锁汁，切时不流汁不发干。","ingredients":["梅花肉"]}]',
 0),
