 '[{"name":"河粉","amount":"300g","iconName":"leaf"},{"name":"牛里脊","amount":"200g","iconName":"beef"},{"name":"豆芽","amount":"100g","iconName":"leaf"},{"name":"韭黄","amount":"50g","iconName":"leaf"},{"name":"老抽","amount":"1勺","iconName":"flask"}]',
