 '[{"stepNumber":1,"title":"切白菜","description":"白菜帮斜刀片成薄片，菜叶撕大块，帮叶分开。","heat":"无需明火","durationSeconds":180,"tip":"斜刀断面大易入味；帮叶熟度不同要分开炒。","ingredients":["白菜帮"]},{"stepNumber":2,"title":"爆香","description":"热油下干辣椒段和蒜片小火爆香。","heat":"中火","durationSeconds":30,"tip":"辣椒别炒糊，糊了整锅发苦。","ingredients":["干辣椒","蒜片"]},{"stepNumber":3,"title":"炒帮","description":"下白菜帮大火翻炒 1 分钟至断生。","heat":"大火","durationSeconds":60,"tip":"先炒帮，耐炒且出水少。","ingredients":["白菜帮"]},{"stepNumber":4,"title":"下叶调味","description":"下白菜叶，加香醋 2 勺、生抽 1 勺、少许糖和盐，大火快炒 1 分钟。","heat":"大火","durationSeconds":60,"tip":"醋沿锅边淋，高温激出酸香。","ingredients":["白菜帮","香醋","生抽"]},{"stepNumber":5,"title":"勾芡出锅","description":"淋薄芡翻匀，出锅前可再点几滴醋增香。","heat":"大火","durationSeconds":20,"tip":"薄芡挂汁，白菜脆爽不出汤。","ingredients":["白菜帮"]}]',
