 '[{"stepNumber":1,"title":"切块焯水","description":"五花肉切 6cm 见方大块，冷水下锅加姜葱料酒焯 5 分钟，温水洗净。","heat":"大火","durationSeconds":300,"tip":"大块才够气派，焯水去腥去沫。","ingredients":["五花肉","小葱"]},{"stepNumber":2,"title":"垫葱姜","description":"砂锅底铺满葱段和姜片，肉块皮朝下码放整齐。","heat":"无需明火","durationSeconds":180,"tip":"垫葱姜防粘底，并贡献葱香。","ingredients":["小葱"]},{"stepNumber":3,"title":"加料慢炖","description":"倒入黄酒 300ml、生抽 3 勺、老抽 1 勺、冰糖 40g，加少量水至齐平，大火烧开转最小火炖 90 分钟。","heat":"大火转小火","durationSeconds":5400,"tip":"酒代水炖是东坡肉特色；小火慢煨至酥而不烂。","ingredients":["五花肉","黄酒","生抽","老抽","冰糖"]},{"stepNumber":4,"title":"翻面继续","description":"将肉块翻至皮朝上，再炖 20 分钟。","heat":"小火","durationSeconds":1200,"tip":"翻面让皮吸足汤汁，成品红亮。","ingredients":["五花肉"]},{"stepNumber":5,"title":"收汁蒸透","description":"将肉移入碗中上笼蒸 20 分钟，原汁收浓后浇在肉上。","heat":"中火","durationSeconds":1200,"tip":"先炖后蒸，入口即化且形状完整。","ingredients":["五花肉"]}]',
