 '[{"stepNumber":1,"title":"切段腌制","description":"猪里脊切 2cm 见方小段，加盐、料酒腌 10 分钟。","heat":"无需明火","durationSeconds":600,"tip":"小块易熟易裹糊。","ingredients":["猪里脊"]},{"stepNumber":2,"title":"挂硬糊","description":"加入 3 勺淀粉和适量水调成厚糊，使每段均匀挂糊。","heat":"无需明火","durationSeconds":120,"tip":"糊要厚且能挂住，炸后才酥脆不回软。","ingredients":["猪里脊","淀粉"]},{"stepNumber":3,"title":"初炸定型","description":"油烧至六成热（约 180℃）下锅炸 2 分钟至定型微黄捞出。","heat":"中火","durationSeconds":120,"tip":"六成热定型，先别翻动。","ingredients":["猪里脊"]},{"stepNumber":4,"title":"复炸酥脆","description":"油温升至八成热复炸 40 秒至金黄酥脆捞出。","heat":"大火","durationSeconds":40,"tip":"复炸逼油，外壳久放仍脆。","ingredients":["猪里脊"]},{"stepNumber":5,"title":"调汁翻裹","description":"锅中加糖、醋、生抽、蒜片和青椒胡萝卜片炒成芡汁，倒入肉段快速翻匀。","heat":"大火","durationSeconds":60,"tip":"芡汁要稠，翻两下即离火，保持酥脆。","ingredients":["青椒","胡萝卜","蒜片"]}]',
