 '[{"stepNumber":1,"title":"处理肉丁","description":"五花肉切 1cm 小丁，肥瘦分开。","heat":"无需明火","durationSeconds":180,"tip":"肉丁小才易炸出酱香。","ingredients":["五花肉"]},{"stepNumber":2,"title":"炸酱","description":"干黄酱 3 勺、甜面酱 1 勺加水澥开；锅中下肥肉丁煸出油，下瘦肉丁炒变色，倒入澥好的酱。","heat":"中火","durationSeconds":300,"tip":"酱要用水澥开再炒，防糊防咸。","ingredients":["五花肉","干黄酱","甜面酱"]},{"stepNumber":3,"title":"小火㸆酱","description":"转最小火慢慢㸆 20 分钟，其间不停搅动，至酱色红亮、油酱分离。","heat":"小火","durationSeconds":1200,"tip":"㸆到油酱分离才叫「炸酱」，这是成败关键。","ingredients":["五花肉","干黄酱"]},{"stepNumber":4,"title":"备菜码","description":"黄瓜切丝，豆芽焯水过凉。","heat":"大火","durationSeconds":120,"tip":"菜码清爽解腻，可再加萝卜丝、青豆。","ingredients":["黄瓜","豆芽"]},{"stepNumber":5,"title":"煮面拌食","description":"手擀面煮熟过凉，浇上炸酱，配菜码拌匀。","heat":"大火","durationSeconds":180,"tip":"面过凉更筋道，拌酱时加菜码更香。","ingredients":["手擀面"]}]',
