 '[{"stepNumber":1,"title":"回温擦干","description":"西冷牛排提前 30 分钟取出回温，厨房纸吸干表面水分，两面撒盐和黑胡椒。","heat":"无需明火","durationSeconds":1800,"tip":"回温后受热均匀；表面越干越易出焦壳。","ingredients":["西冷牛排","黑胡椒碎"]},{"stepNumber":2,"title":"煎第一面","description":"铸铁锅烧至冒烟，下油后放牛排，大火煎 90 秒不翻动。","heat":"大火","durationSeconds":90,"tip":"锅必须足够热才能形成焦壳（美拉德反应）。","ingredients":["西冷牛排"]},{"stepNumber":3,"title":"煎第二面","description":"翻面再煎 90 秒，加入黄油、蒜瓣和迷迭香。","heat":"大火","durationSeconds":90,"tip":"黄油最后加，否则易焦。","ingredients":["西冷牛排","黄油","大蒜","迷迭香"]},{"stepNumber":4,"title":"黄油淋面","description":"用勺舀融化的黄油反复浇在牛排表面 30 秒。","heat":"中火","durationSeconds":30,"tip":"淋油让表面更香更亮，风味更足。","ingredients":["西冷牛排","黄油"]},{"stepNumber":5,"title":"静置切块","description":"出锅静置 5 分钟，逆纹切片，撒黑胡椒。","heat":"无需明火","durationSeconds":300,"tip":"静置让肉汁回流，切开才不流失。","ingredients":["西冷牛排","黑胡椒碎"]}]',
